{"function":"() => {
const props=['outline-style','outline-width','outline-color','box-shadow','border-bottom-color','background-color'];
const els=[...document.querySelectorAll('a[href],button,input,textarea,select,[tabindex]')].filter(e=>e.offsetParent!==null||e.type==='file');
const out=[];
for(const e of els){const b=getComputedStyle(e);const before=props.map(p=>b.getPropertyValue(p));e.focus();const a=getComputedStyle(e);const after=props.map(p=>a.getPropertyValue(p));out.push({el:e.id||e.className||e.tagName, ti:e.tabIndex, focused:document.activeElement===e, changed:props.filter((p,i)=>before[i]!==after[i]).map(p=>p+':'+a.getPropertyValue(p))});e.blur();}
return out;}"}

